function submitWithdrawal(){const bankSelect=document.getElementById('st-withdraw-bank');if(!bankSelect)return;const bankAccountId=bankSelect.value;const amountInput=document.getElementById('st-withdraw-amount');const amount=parseFloat(amountInput.value);if(isNaN(amount)||amount<50000){alert('Số tiền rút tối thiểu là 50.000 đ!');return}
if(amount>walletData.available_balance){alert('Số dư khả dụng trong ví không đủ!');return}
const submitBtn=document.getElementById('st-withdraw-submit-btn');submitBtn.disabled=!0;submitBtn.textContent='Đang gửi yêu cầu...';const url=STConfig.endpoint.replace('/log','/member-dashboard').replace('tracking/v1/member-dashboard','staff-tracking/v1/withdrawals');fetch(url,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-WP-Nonce':STConfig.nonce},body:JSON.stringify({bank_account_id:parseInt(bankAccountId,10),amount:amount})}).then(res=>res.json()).then(data=>{submitBtn.disabled=!1;submitBtn.textContent='Gửi yêu cầu rút tiền';if(data&&data.success){showToast('🎉 Gửi yêu cầu rút tiền thành công! Vui lòng chờ phê duyệt.');selectTab('money')}else{alert((data&&data.error)?data.error:'Gửi yêu cầu rút tiền thất bại!')}}).catch(()=>{submitBtn.disabled=!1;submitBtn.textContent='Gửi yêu cầu rút tiền';alert('Lỗi kết nối máy chủ!')})}
function cancelWithdrawal(id){const baseUrl=STConfig.endpoint.replace('/log','/member-dashboard').replace('tracking/v1/member-dashboard','staff-tracking/v1/withdrawals');fetch(`${baseUrl}/${id}/cancel`,{method:'POST',credentials:'same-origin',headers:{'X-WP-Nonce':STConfig.nonce}}).then(res=>res.json()).then(data=>{if(data&&data.success){showToast('Hủy yêu cầu rút tiền thành công.');selectTab('money')}else{alert((data&&data.error)?data.error:'Hủy yêu cầu rút tiền thất bại!')}}).catch(()=>{alert('Lỗi kết nối máy chủ!')})}
function isSeoCrawler(){const ua=(navigator.userAgent||'').toLowerCase();return/googlebot|google-inspectiontool|bingbot|yandexbot|baiduspider|duckduckbot|facebookexternalhit|twitterbot|linkedinbot|slackbot|whatsapp|telegrambot|applebot|ahrefsbot|semrushbot|mj12bot|screaming frog/.test(ua)}
